{
  "model": "bedrock/global.anthropic.claude-sonnet-5-5",
  "max_tokens": 1024,
  "stream": true,
  "tools": [
    {
      "name": "Bash",
      "description": "Run a shell command",
      "input_schema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string"
          }
        },
        "required": [
          "command"
        ]
      }
    }
  ],
  "messages": [
    {
      "role": "user",
      "content": "Use the Bash tool to run: ls -la"
    }
  ],
  "safeguards": [
    {
      "type": "dangerous_tool_use",
      "classifier_context": {
        "v": 1,
        "permission_mode": "auto"
      }
    }
  ]
}

